  if (!org || org.archivedAt !== null) {
    throw new NotFoundError("Organization", invitation.orgId);
  }

  const user = requireFound(
    await userRepo.findUserById(userId),
    "User",
    userId,
  );
  if (user.email.toLowerCase() !== invitation.email.toLowerCase()) {
    throw new Error("This invitation was sent to a different email address");
  }

  const stamp = toIsoTimestamp(new Date());
  await invitationRepo.markInvitationAccepted(
    invitation.orgId,
    invitation.id,
    stamp,
  );

  const live = await memberRepo.findMember(invitation.orgId, userId);
  if (live) return live;

  // A former member gets their earlier row back: same id, fresh role,
  // inviter and join time, rather than a second membership for the same user.
  const former = await memberRepo.findMemberIncludingArchived(
    invitation.orgId,
    userId,
  );
  const member = former
    ? await memberRepo.reactivateMember(
        invitation.orgId,
        former.id,
        invitation.role,
        invitation.invitedBy,
        stamp,
      )
    : await memberRepo.insertMember(
        invitation.orgId,
        userId,
        invitation.role,
        invitation.invitedBy,
      );

  await emit("member.joined", {
    ...envelope(invitation.orgId, userId),
    memberId: member.id,
    userId,
    role: member.role,
  });

  return member;
}

export async function revokeInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertCan(actor, "member:invite", orgResource(actor.orgId));
  return invitationRepo.revokeInvitation(actor.orgId, invitationId);
}

/**
 * Re-issuing does not mint a new row: the original is revoked and replaced so
 * the audit trail keeps both, and the old link stops working immediately. The
 * replacement keeps the original address and role, and is valid for a fresh
 * 14 days, so an expired invitation can be re-sent too.
 */
export async function resendInvitation(
  actor: Actor,
  invitationId: InvitationId,
): Promise<Invitation> {
  assertOrgScope(actor, actor.orgId);
  assertCan(actor, "member:invite", orgResource(actor.orgId));

  const previous = requireFound(
    await invitationRepo.findInvitationById(actor.orgId, invitationId),
    "Invitation",
    invitationId,
  );
  if (previous.acceptedAt !== null || previous.revokedAt !== null) {
    throw new Error("Only pending or expired invitations can be re-sent");
  }

  await invitationRepo.revokeInvitation(actor.orgId, invitationId);

  return inviteMember(actor, {
    orgId: actor.orgId,
    email: previous.email,
    role: invitableRoleSchema.parse(previous.role),
  });
}

